let token = null;        // { valor, expiraEn }
let renovando = null;    // promesa en curso

async function obtenerToken() {
  if (token && Date.now() < token.expiraEn - 45000) return token.valor;
  if (!renovando) {
    renovando = pedirTokenAlServidor().finally(() => { renovando = null; });
  }
  token = await renovando;
  return token.valor;
}

